{"row_id": "C9999A00099:S-01:S-01", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-01", "heading": "Working from a residence", "text": "An employee who performs duties at a place of residence may deduct the additional running expenses of the room set aside for those duties.", "version_is_current": true}
{"row_id": "C9999A00099:S-02:S-02", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-02", "heading": "Occupancy expenses of a residence", "text": "Rent, mortgage interest and rates for a home are occupancy expenses and are private unless the home is a place of business.", "version_is_current": true}
{"row_id": "C9999A00099:S-03:S-03", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-03", "heading": "Home based business records", "text": "A business run from a home keeps a record of the floor area used for the business.", "version_is_current": true}
{"row_id": "C9999A00099:S-04:S-04", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-04", "heading": "Motor vehicle expenses", "text": "An entity may deduct the cost of using a car for work travel if a logbook is kept for the year.", "version_is_current": true}
{"row_id": "C9999A00099:S-05:S-05", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-05", "heading": "Logbook requirement", "text": "A logbook records each journey, its purpose and the kilometres travelled.", "version_is_current": true}
{"row_id": "C9999A00099:S-06:S-06", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-06", "heading": "Private use of a car", "text": "Travel between home and work is private travel and is not deductible.", "version_is_current": true}
{"row_id": "C9999A00099:S-07:S-07", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-07", "heading": "Fuel and oil", "text": "Fuel and oil for a motor vehicle are running expenses of the vehicle.", "version_is_current": true}
{"row_id": "C9999A00099:S-08:S-08", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-08", "heading": "Overnight travel", "text": "An employee who travels away from home overnight for work may deduct accommodation and meal costs.", "version_is_current": true}
{"row_id": "C9999A00099:S-09:S-09", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-09", "heading": "Entertainment", "text": "A meal or drink provided as entertainment for a client is not deductible.", "version_is_current": true}
{"row_id": "C9999A00099:S-10:S-10", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-10", "heading": "Gifts", "text": "A gift of money to a deductible gift recipient is deductible if a receipt is held.", "version_is_current": true}
{"row_id": "C9999A00099:S-11:S-11", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-11", "heading": "Compulsory uniforms", "text": "The cost of buying and washing a compulsory uniform is deductible; ordinary clothing is private.", "version_is_current": true}
{"row_id": "C9999A00099:S-12:S-12", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-12", "heading": "Self education", "text": "Course fees are deductible if the course maintains a skill used in current employment.", "version_is_current": true}
{"row_id": "C9999A00099:S-13:S-13", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-13", "heading": "Tools and equipment", "text": "An employee may deduct the cost of tools and equipment used for work over their effective life.", "version_is_current": true}
{"row_id": "C9999A00099:S-14:S-14", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-14", "heading": "Depreciating assets", "text": "The decline in value of a depreciating asset is worked out over its effective life.", "version_is_current": true}
{"row_id": "C9999A00099:S-15:S-15", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-15", "heading": "Immediate write off", "text": "A small entity may write off an asset in the year it is first used.", "version_is_current": true}
{"row_id": "C9999A00099:S-16:S-16", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-16", "heading": "Main residence", "text": "A capital gain on the sale of a dwelling that was the main residence is disregarded.", "version_is_current": true}
{"row_id": "C9999A00099:S-17:S-17", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-17", "heading": "Rental property sale", "text": "A capital gain on selling a rental property is included in assessable income.", "version_is_current": true}
{"row_id": "C9999A00099:S-18:S-18", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-18", "heading": "Rental income", "text": "Rent received from a tenant is assessable income of the owner.", "version_is_current": true}
{"row_id": "C9999A00099:S-19:S-19", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-19", "heading": "Repairs", "text": "The cost of repairs to a rental property is deductible, but an initial repair or improvement is capital.", "version_is_current": true}
{"row_id": "C9999A00099:S-20:S-20", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-20", "heading": "Dividends", "text": "A dividend paid by a company to a shareholder is assessable income, and a franking credit may attach.", "version_is_current": true}
{"row_id": "C9999A00099:S-21:S-21", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-21", "heading": "Loans to shareholders", "text": "A loan from a private company to a shareholder is treated as a dividend unless it is put on complying terms.", "version_is_current": true}
{"row_id": "C9999A00099:S-22:S-22", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-22", "heading": "Beneficiaries", "text": "A beneficiary is assessed on their share of the net income of a trust.", "version_is_current": true}
{"row_id": "C9999A00099:S-23:S-23", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-23", "heading": "Partners", "text": "A partner is assessed on their share of the net income of the partnership.", "version_is_current": true}
{"row_id": "C9999A00099:S-24:S-24", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-24", "heading": "Registration", "text": "An entity must register for GST when its turnover reaches the registration turnover.", "version_is_current": true}
{"row_id": "C9999A00099:S-25:S-25", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-25", "heading": "Tax invoices", "text": "A tax invoice must be held before an input tax credit is claimed.", "version_is_current": true}
{"row_id": "C9999A00099:S-26:S-26", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-26", "heading": "Input tax credits", "text": "An entity claims input tax credits for purchases made in carrying on its enterprise.", "version_is_current": true}
{"row_id": "C9999A00099:S-27:S-27", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-27", "heading": "Activity statements", "text": "An activity statement must be lodged by its due date each quarter.", "version_is_current": true}
{"row_id": "C9999A00099:S-28:S-28", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-28", "heading": "Failure to lodge", "text": "A failure to lodge on time penalty applies to a return lodged after its due date.", "version_is_current": true}
{"row_id": "C9999A00099:S-29:S-29", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-29", "heading": "General interest charge", "text": "General interest charge accrues daily on an unpaid tax debt.", "version_is_current": true}
{"row_id": "C9999A00099:S-30:S-30", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-30", "heading": "Payment plans", "text": "The Commissioner may allow a tax debt to be paid by instalments.", "version_is_current": true}
{"row_id": "C9999A00099:S-31:S-31", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-31", "heading": "Record keeping", "text": "An entity must keep records of its income and expenses for the retention period.", "version_is_current": true}
{"row_id": "C9999A00099:S-32:S-32", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-32", "heading": "Super guarantee", "text": "An employer must pay super contributions for each eligible employee by the due date.", "version_is_current": true}
{"row_id": "C9999A00099:S-33:S-33", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-33", "heading": "Contractors", "text": "A worker engaged under a contract for services is a contractor, not an employee.", "version_is_current": true}
{"row_id": "C9999A00099:S-34:S-34", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-34", "heading": "Withholding", "text": "An employer withholds an amount from salary or wages paid to an employee.", "version_is_current": true}
{"row_id": "C9999A00099:S-35:S-35", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-35", "heading": "Car fringe benefits", "text": "A car provided to an employee for private use is a car fringe benefit of the employer.", "version_is_current": true}
{"row_id": "C9999A00099:S-36:S-36", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-36", "heading": "Bad debts", "text": "A debt written off as bad may be deducted in the year it is written off.", "version_is_current": true}
{"row_id": "C9999A00099:S-37:S-37", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-37", "heading": "Tax losses", "text": "A tax loss may be carried forward and deducted in a later income year.", "version_is_current": true}
{"row_id": "C9999A00099:S-38:S-38", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-38", "heading": "Foreign income", "text": "A resident is assessed on foreign income and may claim an offset for foreign tax paid.", "version_is_current": true}
{"row_id": "C9999A00099:S-39:S-39", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-39", "heading": "Levy surcharge", "text": "A person without private hospital cover may pay a levy surcharge.", "version_is_current": true}
{"row_id": "C9999A00099:S-40:S-40", "register_id": "C9999A00099", "act": "Income Tax Assessment Act 1997", "section": "S-40", "heading": "Digital assets", "text": "A digital asset held as an investment is a capital gains tax asset.", "version_is_current": true}
